// Original streaming phase-vocoder pitch shifter. 2048-sample frame, 8x overlap.
class SpectralPitch {
 constructor(){this.n=2048;this.hop=256;this.rover=1792;for(const k of ['input','output','real','imag','accum','lastPhase','sumPhase','magn','freq'])this[k]=new Float32Array(2048);this.window=Float32Array.from({length:2048},(_,i)=>.5-.5*Math.cos(2*Math.PI*i/2048))}
 fft(inverse){const n=this.n,r=this.real,im=this.imag;for(let i=1,j=0;i<n;i++){let bit=n>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j){let v=r[i];r[i]=r[j];r[j]=v;v=im[i];im[i]=im[j];im[j]=v}}for(let size=2;size<=n;size*=2){const angle=(inverse?2:-2)*Math.PI/size,wr=Math.cos(angle),wi=Math.sin(angle);for(let start=0;start<n;start+=size){let cr=1,ci=0;for(let j=0;j<size/2;j++){let a=start+j,b=a+size/2,tr=cr*r[b]-ci*im[b],ti=cr*im[b]+ci*r[b];r[b]=r[a]-tr;im[b]=im[a]-ti;r[a]+=tr;im[a]+=ti;let nr=cr*wr-ci*wi;ci=cr*wi+ci*wr;cr=nr}}}if(inverse)for(let i=0;i<n;i++){r[i]/=n;im[i]/=n}}
 sample(x,ratio){const result=this.output[this.rover-1792];this.input[this.rover++]=x;if(this.rover===this.n){this.rover=1792;this.frame(ratio)}return result}
 frame(ratio){const n=this.n,half=n/2,expected=2*Math.PI*this.hop/n;for(let i=0;i<n;i++){this.real[i]=this.input[i]*this.window[i];this.imag[i]=0}this.fft(false);this.magn.fill(0);this.freq.fill(0);for(let k=0;k<=half;k++){const re=this.real[k],im=this.imag[k],m=Math.hypot(re,im),phase=Math.atan2(im,re);let delta=phase-this.lastPhase[k]-k*expected;this.lastPhase[k]=phase;delta-=2*Math.PI*Math.round(delta/(2*Math.PI));const actual=k+delta/expected,bin=Math.round(k*ratio);if(bin<=half){this.magn[bin]+=m;this.freq[bin]=actual*ratio}}
 this.real.fill(0);this.imag.fill(0);for(let k=0;k<=half;k++){this.sumPhase[k]+=(this.freq[k]-k)*expected+k*expected;const phase=this.sumPhase[k];this.real[k]=this.magn[k]*Math.cos(phase);this.imag[k]=this.magn[k]*Math.sin(phase);if(k>0&&k<half){this.real[n-k]=this.real[k];this.imag[n-k]=-this.imag[k]}}this.fft(true);for(let i=0;i<n;i++)this.accum[i]+=this.real[i]*this.window[i]/3;for(let i=0;i<this.hop;i++)this.output[i]=this.accum[i];this.accum.copyWithin(0,this.hop);this.accum.fill(0,n-this.hop);this.input.copyWithin(0,this.hop)}
}
class PitchGate extends AudioWorkletProcessor {
 constructor(){super();this.pitch=[new SpectralPitch(),new SpectralPitch()];this.env=0;this.gain=1;this.s={transpose:0,gateOn:false,gate:-60,mode:'mono'};this.port.onmessage=e=>{if(e.data.transpose!==this.s.transpose)this.pitch=[new SpectralPitch(),new SpectralPitch()];this.s=e.data}}
 process(inputs,outputs){const input=inputs[0],out=outputs[0];if(!input.length)return true;const ratio=Math.pow(2,this.s.transpose/12),threshold=Math.pow(10,this.s.gate/20);for(let i=0;i<out[0].length;i++){const l=input[0][i],r=input[1]?.[i]??l;this.env=Math.max(Math.abs(l),Math.abs(r),this.env*.9995);const goal=this.s.gateOn&&this.env<threshold?0:1;this.gain+=(goal-this.gain)*(goal?.01:.001);for(let c=0;c<out.length;c++){const x=(this.s.mode==='mono'?l:(c?r:l))*this.gain;out[c][i]=this.s.transpose===0?x:this.pitch[c].sample(x,ratio)}}return true}
}registerProcessor('pitch-gate',PitchGate);
